func TestPay(t *testing.T) {
	rec := &recorder{}
	s := &Service{Store: NewStore(Invoice{ID: "i1", TotalCents: 1000, Status: StatusOpen}), Ledger: &Ledger{}, Notifier: rec}
	if err := s.Pay("i1", 1000); err != nil {
		t.Fatal(err)
	}
	if err := s.Pay("i1", 1); !errors.Is(err, ErrOverpayment) {
		t.Fatalf("overpayment err = %v", err)
	}
	if got := s.Ledger.Balance(AccountCash); got != 1000 {
		t.Fatalf("cash = %d", got)
	}
	if len(rec.events) != 1 || rec.events[0].Type != EventPaid {
		t.Fatalf("events = %v", rec.events)
	}
}

